         outline: 3px solid rgba(157, 178, 255, 0.45);
         outline-offset: 2px;
       }

       .status {
         min-height: 1.25em;
         margin: 0;
         color: var(--accent-strong);
         font-size: 0.95rem;
       }
     </style>
   </head>
   <body>
     <main class="card">
       <h1>Terms of Use</h1>
       <p>Please review and accept the terms before continuing.</p>

       <form id="consent-form" novalidate>
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="terms"
               name="terms"
               type="checkbox"
               required
               aria-describedby="terms-help"
             />
             <div>
               <label for="terms">I agree to the terms of use</label>
               <p class="helper-text" id="terms-help">
                 You must accept the terms to submit this form.
               </p>
             </div>
           </div>
         </div>

         <button type="submit">Submit</button>
         <p class="status" id="status" aria-live="polite"></p>
       </form>
     </main>

     <script>
       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("terms");
       const status = document.getElementById("status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!checkbox.checked) {
           checkbox.setCustomValidity("Please agree to the terms of use.");
           form.reportValidity();
           checkbox.setCustomValidity("");
           status.textContent = "";
           return;
         }

         status.textContent = "Consent submitted.";
         form.reset();
       });
     </script>
   </body>
 </html>

